package com.ias.finance;

import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.finance.FeeGroup.*;
import static com.ias.finance.JdbcFeeGroups.*;

class QuoteSourcesTest {
 JdbcFeeGroupsTest f;JdbcQuoteSources sources;Submit command;QuoteDetails details;UUID relation=UUID.randomUUID();
 @BeforeEach void setup()throws Exception{f=new JdbcFeeGroupsTest();f.setup();f.owner=new Identity(1,2,UUID.nameUUIDFromBytes(("finance:1:2:"+relation).getBytes(StandardCharsets.UTF_8)));f.store.open(f.actor,f.owner,UUID.randomUUID());sources=new JdbcQuoteSources(f.source,f.authority);command=f.command(0,250000,200000,Set.of());details=new QuoteDetails(true,"独立持久源意图完整报价",f.details(command).kinds());}
 JdbcQuoteSources.Source register()throws Exception{return sources.register(f.actor,f.owner,command,details);}
 JdbcQuoteSources.Source abort()throws Exception{return sources.abort(f.actor,f.owner,command.operationId(),command.applicationId(),0,JdbcFeeGroups.quoteDigest(f.owner,command,details),"原发起人显式中止尚未提交的源操作");}
 @Test void intentSurvivesDependencyFailureAndQueryIsPureAndFullyBound()throws Exception{
  var registered=register();assertEquals("IN_PROGRESS",registered.state());long events=f.count("finance_quote_source_event"),operations=f.count("finance_operation");var line=command.additions().getFirst();assertEquals(registered,sources.verified(registered.binding(),line.ticketId(),line.roundId(),relation));assertEquals(events,f.count("finance_quote_source_event"));assertEquals(operations,f.count("finance_operation"));
  assertThrows(IllegalStateException.class,()->sources.verified(registered.binding(),line.ticketId(),UUID.randomUUID(),relation));assertThrows(IllegalStateException.class,()->sources.verified(registered.binding(),line.ticketId(),line.roundId(),UUID.randomUUID()));
  var b=registered.binding();assertThrows(IllegalStateException.class,()->sources.verified(new JdbcQuoteSources.Binding(new Actor(1,99),b.owner(),b.operationId(),b.quoteId(),b.expectedGroupVersion(),b.commandDigest()),line.ticketId(),line.roundId(),relation));
  Access failed=new Wrapped(f.authority){public void submission(Actor a,Identity o,Submit c,QuoteDetails d){throw new com.ias.trust.Problem(503,"OWNER_UNAVAILABLE");}};
  assertThrows(com.ias.trust.Problem.class,()->new JdbcFeeGroups(f.source,failed).submit(f.actor,f.owner,command,details));assertEquals("IN_PROGRESS",sources.read(f.actor,f.owner,command.operationId()).state());assertEquals(0,f.count("finance_quote_version"));assertEquals(0,f.count("finance_quote_source_outbox"));
 }
 @Test void abortWinsAgainstLateCommitAndNeverRevivesOriginalUuid()throws Exception{register();var aborted=abort();assertEquals("ABORTED",aborted.state());assertEquals(aborted,abort());assertEquals("FINANCE_SOURCE_ABORTED",assertThrows(IllegalStateException.class,()->f.store.submit(f.actor,f.owner,command,details)).getMessage());assertEquals(0,f.count("finance_quote_version"));assertEquals(0,f.store.read(f.actor,f.owner).version());assertEquals(1,f.count("finance_quote_source_outbox"));assertThrows(IllegalStateException.class,()->sources.abort(f.actor,f.owner,command.operationId(),command.applicationId(),0,JdbcFeeGroups.quoteDigest(f.owner,command,details),"不得用另一个原因覆盖第一次ABORT依据"));}
 @Test void committedWinsAndOriginalReplayDoesNotPrepareAgain()throws Exception{
  var count=new java.util.concurrent.atomic.AtomicInteger();Access once=new Wrapped(f.authority){public void submission(Actor a,Identity o,Submit c,QuoteDetails d){if(count.incrementAndGet()>1)throw new IllegalStateException("MUST_NOT_PREPARE_AGAIN");}};var store=new JdbcFeeGroups(f.source,once);var receipt=store.submit(f.actor,f.owner,command,details);var committed=sources.read(f.actor,f.owner,command.operationId());assertEquals("COMMITTED",committed.state());assertEquals(JdbcMoneyLedger.digest(receipt),committed.resultDigest());assertEquals(committed,abort());assertEquals(receipt,store.submit(f.actor,f.owner,command,details));assertEquals(1,count.get());assertEquals(1,f.count("finance_quote_source_outbox"));assertEquals(2,f.count("finance_quote_source_event"));
 }
 @Test void sourceOutboxFailureRollsBackQuoteAndTerminalButNotPriorIntent()throws Exception{
  register();try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_quote_source_outbox ADD CONSTRAINT fail_source CHECK(event_type<>'FINANCE_QUOTE_SOURCE_COMMITTED')");}long count=f.count("finance_operation");
  assertThrows(Exception.class,()->f.store.submit(f.actor,f.owner,command,details));assertEquals("IN_PROGRESS",sources.read(f.actor,f.owner,command.operationId()).state());assertEquals(0,f.count("finance_quote_version"));assertEquals(count,f.count("finance_operation"));assertEquals(count,f.count("finance_audit"));assertEquals(count,f.count("finance_outbox"));assertEquals(1,f.count("finance_quote_source_event"));assertEquals(0,f.store.read(f.actor,f.owner).version());
  try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_quote_source_outbox DROP CONSTRAINT fail_source");}f.store.submit(f.actor,f.owner,command,details);assertEquals("COMMITTED",sources.read(f.actor,f.owner,command.operationId()).state());
 }
 @Test void abortOutboxFailureLeavesIntentAndOriginalAbortRecovers()throws Exception{register();try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_quote_source_outbox ADD CONSTRAINT fail_abort CHECK(event_type<>'FINANCE_QUOTE_SOURCE_ABORTED')");}assertThrows(Exception.class,this::abort);assertEquals("IN_PROGRESS",sources.read(f.actor,f.owner,command.operationId()).state());assertEquals(1,f.count("finance_quote_source_event"));try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_quote_source_outbox DROP CONSTRAINT fail_abort");}abort();assertEquals(1,f.count("finance_quote_source_outbox"));}
 @Test void abortAndCommitRaceExactlyOneTerminal()throws Exception{register();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var commit=pool.submit(()->{gate.await();try{f.store.submit(f.actor,f.owner,command,details);return true;}catch(IllegalStateException e){assertEquals("FINANCE_SOURCE_ABORTED",e.getMessage());return false;}});var abort=pool.submit(()->{gate.await();return abort();});gate.countDown();boolean won=commit.get(5,TimeUnit.SECONDS);var result=abort.get(5,TimeUnit.SECONDS);assertEquals(won?"COMMITTED":"ABORTED",result.state());assertEquals(won?1:0,f.count("finance_quote_version"));assertEquals(1,f.count("finance_quote_source_outbox"));assertEquals(2,f.count("finance_quote_source_event"));}}
 @Test void missingIsNotAbortedAndDifferentParametersCannotTakeOverUuid()throws Exception{long before=f.count("finance_quote_source");assertThrows(SecurityException.class,()->sources.read(f.actor,f.owner,command.operationId()));assertThrows(SecurityException.class,this::abort);assertEquals(before,f.count("finance_quote_source"));register();assertThrows(IllegalStateException.class,()->sources.register(f.actor,f.owner,command,new QuoteDetails(false,details.pricingDescription(),details.kinds())));f.allowed.set(false);assertThrows(SecurityException.class,this::abort);assertThrows(SecurityException.class,()->sources.read(f.actor,f.owner,command.operationId()));}
 @Test void registeredQuoteUuidCannotBeUsedForOtherFinanceActions()throws Exception{register();assertThrows(IllegalStateException.class,()->f.store.cost(f.actor,f.owner,command.operationId(),0,new CostFact(UUID.randomUUID(),100,null,"不能借资金动作抢占报价源UUID")));assertEquals("IN_PROGRESS",sources.read(f.actor,f.owner,command.operationId()).state());}
 @Test void unknownSourceRegistrationDoesNotInventAbortAndDiscardsConnection()throws Exception{
  for(boolean actuallyCommitted:List.of(false,true)){
   var c=f.command(0,10000,200000,Set.of());var d=new QuoteDetails(true,"源登记提交未知的完整参数",f.details(c).kinds());java.sql.Connection physical=f.source.getConnection();var resets=new java.util.concurrent.atomic.AtomicInteger();var closes=new java.util.concurrent.atomic.AtomicInteger();var aborts=new java.util.concurrent.atomic.AtomicInteger();
   var proxy=(java.sql.Connection)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{java.sql.Connection.class},(p,m,args)->{switch(m.getName()){case "commit"->{if(actuallyCommitted)physical.commit();throw new java.sql.SQLException("SOURCE_COMMIT_ACK_UNKNOWN");}case "rollback"->throw new java.sql.SQLException("SOURCE_ROLLBACK_UNKNOWN");case "abort"->{aborts.incrementAndGet();physical.close();return null;}case "close"->{closes.incrementAndGet();physical.close();return null;}case "setAutoCommit"->{if(Boolean.TRUE.equals(args[0]))resets.incrementAndGet();}}try{return m.invoke(physical,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});
   var faulty=org.mockito.Mockito.mock(javax.sql.DataSource.class);org.mockito.Mockito.when(faulty.getConnection()).thenReturn(proxy);var failure=assertThrows(java.sql.SQLException.class,()->new JdbcQuoteSources(faulty,f.authority).register(f.actor,f.owner,c,d));assertEquals("OPERATION_RESULT_UNKNOWN",failure.getMessage());assertEquals(1,failure.getCause().getSuppressed().length);assertEquals(1,aborts.get());assertEquals(0,resets.get());assertEquals(0,closes.get());assertTrue(physical.isClosed());
   if(actuallyCommitted)assertEquals("IN_PROGRESS",sources.read(f.actor,f.owner,c.operationId()).state());else assertThrows(SecurityException.class,()->sources.read(f.actor,f.owner,c.operationId()));
   // Neither 404 nor timeout aborted the original key; explicitly register/recover then abort it.
   sources.register(f.actor,f.owner,c,d);sources.abort(f.actor,f.owner,c.operationId(),c.applicationId(),0,JdbcFeeGroups.quoteDigest(f.owner,c,d),"原提交结果核对后显式中止源操作");assertThrows(IllegalStateException.class,()->f.store.submit(f.actor,f.owner,c,d));
  }
 } static class Wrapped implements Access {
  final Access base;Wrapped(Access base){this.base=base;}public void current(Actor a,Identity o,String action){base.current(a,o,action);}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){base.submission(a,o,c,d);}public void approval(Actor a,Identity o,UUID id,ApprovalFact f){base.approval(a,o,id,f);}public void verifiedCost(Actor a,Identity o,CostFact f){base.verifiedCost(a,o,f);}public void execution(Actor a,Identity o,UUID line){base.execution(a,o,line);}
 }
}
